// 逃逸：返回局部变量指针
func newUser() *User {
	u := User{Name: "alice"} // u 逃逸到堆
	return &u
}

// 不逃逸：值传递
func copyUser(u User) User {
	u.Name = "bob" // u 在栈上
	return u
}

// 逃逸：赋值给 interface{}
func logValue(v any) { fmt.Println(v) }
func main() {
	x := 42
	logValue(x) // x 被装箱到 interface{}，逃逸到堆
}

// $ go build -gcflags='-m' ./...
// ./main.go:3:2: moved to heap: u

// 泄漏：子切片持有大数组引用
func getHeader(data []byte) []byte {
	return data[:16] // 持有整个 data 底层数组的引用
}

// 修复：copy 出来
func getHeader(data []byte) []byte {
	header := make([]byte, 16)
	copy(header, data[:16])
	return header // 独立的小数组，data 可以被 GC
}
